import re


def scan() -> int:
    subject = 'word 123 another 4567 x 89 ' * 400000
    return len(re.findall(r'[a-z]+', subject))


print('matches', scan())
# Retained unrelated allocations force subsequent normal collections.
kept = [str(i) + 'a' * 1000000 for i in range(150)]
print('retained', sum(len(s) for s in kept))
with open('/proc/self/status') as file:
    for line in file.read().splitlines():
        if line.startswith('VmRSS:'):
            print(line)
